import{d as o,N as a,i as t,l as d}from"./chunks/framework.DAESqsOv.js";const u=JSON.parse('{"title":"常见问题","description":"","frontmatter":{"title":"常见问题","outline":"deep"},"headers":[],"relativePath":"rich-text/faq.md","filePath":"rich-text/faq.md","lastUpdated":1778951341000}'),i={name:"rich-text/faq.md"};function c(l,e,r,n,h,s){return a(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="生产环境可以直接使用吗" tabindex="-1">生产环境可以直接使用吗 <a class="header-anchor" href="#生产环境可以直接使用吗" aria-label="Permalink to &quot;生产环境可以直接使用吗&quot;">​</a></h2><p>组件还在持续迭代中，建议用于生产前结合业务场景做完整测试。发现问题可反馈至 <code>norio-office@qq.com</code>。</p><h2 id="为什么需要显式引入样式" tabindex="-1">为什么需要显式引入样式 <a class="header-anchor" href="#为什么需要显式引入样式" aria-label="Permalink to &quot;为什么需要显式引入样式&quot;">​</a></h2><p>组件样式会作为独立 CSS 文件发布，推荐在应用入口显式引入：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@norio-office/rich-text/style.css&#39;</span></span></code></pre></div><p>这样可以避免不同构建工具对 CSS side effects 处理不一致导致样式缺失。</p><h2 id="为什么推荐使用-jsoncontent" tabindex="-1">为什么推荐使用 <code>JSONContent</code> <a class="header-anchor" href="#为什么推荐使用-jsoncontent" aria-label="Permalink to &quot;为什么推荐使用 `JSONContent`&quot;">​</a></h2><p><code>JSONContent</code> 和编辑器内部结构一致，回显更稳定，也更适合再次进入编辑态。单人模式下建议优先保存 JSON；只读展示时再按场景导出 HTML、PDF 或图片。</p><h2 id="为什么上传要交给业务层" tabindex="-1">为什么上传要交给业务层 <a class="header-anchor" href="#为什么上传要交给业务层" aria-label="Permalink to &quot;为什么上传要交给业务层&quot;">​</a></h2><p>每个业务系统的上传接口、鉴权方式、存储平台、返回结构都不同。组件只负责把用户选择的 <code>File</code> 交给上传 hook，并在 hook 返回最终 URL 后插入内容。</p><p>组件不会内置业务上传接口，也不会自动回退为 base64/blob URL。</p><h2 id="页面拖拽上传如何分流" tabindex="-1">页面拖拽上传如何分流 <a class="header-anchor" href="#页面拖拽上传如何分流" aria-label="Permalink to &quot;页面拖拽上传如何分流&quot;">​</a></h2><p>页面拖拽上传会按文件类型分流：</p><ul><li><code>image/*</code> 走 <code>uploadImage</code></li><li><code>video/*</code> 走 <code>uploadVideo</code></li><li>其他格式走 <code>uploadFile</code>，并插入本地文件卡片</li></ul><p>如果没有传对应上传 hook，业务侧需要自行处理无法上传的提示或接入边界。</p><h2 id="preview-模式和-editable-false-有什么区别" tabindex="-1"><code>preview</code> 模式和 <code>editable=false</code> 有什么区别 <a class="header-anchor" href="#preview-模式和-editable-false-有什么区别" aria-label="Permalink to &quot;`preview` 模式和 `editable=false` 有什么区别&quot;">​</a></h2><p><code>editable=false</code> 更偏向关闭编辑能力，但仍保留原有编辑器壳层。<code>mode=&quot;preview&quot;</code> 则会进入只读预览外壳，工具栏隐藏，并支持更适合阅读场景的大纲布局和窄屏缩放。</p><h2 id="水印会写入编辑器内容吗" tabindex="-1">水印会写入编辑器内容吗 <a class="header-anchor" href="#水印会写入编辑器内容吗" aria-label="Permalink to &quot;水印会写入编辑器内容吗&quot;">​</a></h2><p>不会。<code>watermark</code> 只作为页面视觉层渲染，不写入编辑器 JSON，也不会影响 <code>getText()</code> 的纯文本结果。PDF、图片和打印导出会保留水印。</p><h2 id="mention-search-为什么不像普通事件" tabindex="-1"><code>@mention-search</code> 为什么不像普通事件 <a class="header-anchor" href="#mention-search-为什么不像普通事件" aria-label="Permalink to &quot;`@mention-search` 为什么不像普通事件&quot;">​</a></h2><p><code>mention-search</code> 是函数式监听写法，对应 <code>onMentionSearch</code> prop。Vue 模板里的 <code>@mention-search=&quot;handler&quot;</code> 会作为函数 prop 传入组件，可直接返回数组或 <code>Promise</code>。</p><p><code>mention</code> 默认关闭，只有传入 <code>:mention=&quot;true&quot;</code> 后，输入 <code>@</code> 才会打开候选面板并调用搜索函数。</p><h2 id="点击提及候选项会直接插入吗" tabindex="-1">点击提及候选项会直接插入吗 <a class="header-anchor" href="#点击提及候选项会直接插入吗" aria-label="Permalink to &quot;点击提及候选项会直接插入吗&quot;">​</a></h2><p>不会。点击候选项只会触发 <code>mention-item-click</code> 并选中当前项；点击弹窗底部“提及”按钮才会插入结构化提及节点并触发 <code>mention-submit</code>。关闭弹窗或不点击“提及”时，编辑器会保留普通 <code>@</code> 文本。</p><h2 id="白名单-props-不传时会怎样" tabindex="-1">白名单 Props 不传时会怎样 <a class="header-anchor" href="#白名单-props-不传时会怎样" aria-label="Permalink to &quot;白名单 Props 不传时会怎样&quot;">​</a></h2><p>不传时，内置导出项、插入菜单项和工具栏动作默认全部可用。只有当你显式传了数组，组件才会进入白名单裁剪模式。</p><h2 id="什么时候使用外置目录组件" tabindex="-1">什么时候使用外置目录组件 <a class="header-anchor" href="#什么时候使用外置目录组件" aria-label="Permalink to &quot;什么时候使用外置目录组件&quot;">​</a></h2><p>内置大纲适合默认编辑器布局。如果你希望把目录放到业务系统自己的侧栏、抽屉或固定区域里，可以设置 <code>:show-outline=&quot;false&quot;</code>，再使用 <code>RichTextOutline</code> 接收编辑器实例。</p><h2 id="协同模式为什么不能依赖-modelvalue-初始化" tabindex="-1">协同模式为什么不能依赖 <code>modelValue</code> 初始化 <a class="header-anchor" href="#协同模式为什么不能依赖-modelvalue-初始化" aria-label="Permalink to &quot;协同模式为什么不能依赖 `modelValue` 初始化&quot;">​</a></h2><p>协同模式下的真实数据源是 <code>Yjs</code> 文档。组件仍会 emit JSON 快照，但外部 <code>modelValue</code> 的变化不会再反向写入编辑器。</p><p>默认情况下组件不会把 <code>modelValue</code> 写入空的协同 fragment。如果是后端已有 Yjs 快照，必须以快照为准，不要传 <code>initializeContent: true</code>。如果是全新的空房间，业务侧先确认当前客户端拥有初始化权，再传 <code>initializeContent: true</code> 和 <code>initialContent</code>。</p><h2 id="富文本协同的-documenttype-用什么" tabindex="-1">富文本协同的 <code>documentType</code> 用什么 <a class="header-anchor" href="#富文本协同的-documenttype-用什么" aria-label="Permalink to &quot;富文本协同的 `documentType` 用什么&quot;">​</a></h2><p>统一协同服务里当前富文本组件的类型是 <code>rich</code>。不要把它作为未来 Word 组件的 <code>documentType=word</code> 接入。</p><p>同一个协同房间里的所有客户端必须使用同一个 <code>field</code>，普通一文档一编辑器场景固定用 <code>content</code>。</p><h2 id="随包-yjs-服务适合生产吗" tabindex="-1">随包 Yjs 服务适合生产吗 <a class="header-anchor" href="#随包-yjs-服务适合生产吗" aria-label="Permalink to &quot;随包 Yjs 服务适合生产吗&quot;">​</a></h2><p>不适合直接当生产服务使用。随包 <code>yjs/</code> 示例主要用于快速验证协同接入，它是最小 WebSocket 服务示例，默认纯内存运行，重启后文档状态会丢失。</p><h2 id="本地文件卡片适合什么场景" tabindex="-1">本地文件卡片适合什么场景 <a class="header-anchor" href="#本地文件卡片适合什么场景" aria-label="Permalink to &quot;本地文件卡片适合什么场景&quot;">​</a></h2><p>适合在文档里插入业务附件、下载文件入口、材料清单等。业务侧可以监听 <code>local-file-click</code>、<code>local-file-download</code> 和 <code>upload-error</code> 等事件，再决定如何预览、鉴权和下载。</p><h2 id="后续增加公开能力时文档应补什么" tabindex="-1">后续增加公开能力时文档应补什么 <a class="header-anchor" href="#后续增加公开能力时文档应补什么" aria-label="Permalink to &quot;后续增加公开能力时文档应补什么&quot;">​</a></h2><p>建议每次补齐三类内容：</p><ol><li>功能说明</li><li>接入示例</li><li>限制或注意事项</li></ol>',42)])])}const m=o(i,[["render",c]]);export{u as __pageData,m as default};
